CREATE TABLE attachments (
    id TEXT PRIMARY KEY NOT NULL,
    cipher_id TEXT NOT NULL,
    file_name TEXT NOT NULL,
    file_size_bytes INTEGER NOT NULL CHECK (file_size_bytes >= 0),
    encrypted_key TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    organization_id TEXT,
    storage_key TEXT,
    FOREIGN KEY (cipher_id) REFERENCES ciphers(id) ON DELETE CASCADE
);

CREATE TABLE attachments_pending (
    id TEXT PRIMARY KEY NOT NULL,
    cipher_id TEXT NOT NULL,
    file_name TEXT NOT NULL,
    file_size_bytes INTEGER NOT NULL CHECK (file_size_bytes >= 0),
    encrypted_key TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    organization_id TEXT,
    FOREIGN KEY (cipher_id) REFERENCES ciphers(id) ON DELETE CASCADE
);

CREATE TABLE auth_requests (
    id TEXT PRIMARY KEY NOT NULL,
    user_id TEXT NOT NULL,
    request_device_id TEXT NOT NULL,
    device_type INTEGER NOT NULL,
    request_ip TEXT NOT NULL,
    access_code TEXT NOT NULL,
    public_key TEXT NOT NULL,
    security_stamp TEXT NOT NULL,
    encrypted_key TEXT,
    master_password_hash TEXT,
    approved INTEGER,
    created_at TEXT NOT NULL,
    expires_at TEXT NOT NULL,
    responded_at TEXT,
    authenticated_at TEXT,
    response_device_id TEXT,
    account_snapshot TEXT,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE ciphers (
    id TEXT PRIMARY KEY NOT NULL,
    user_id TEXT NOT NULL,
    organization_id TEXT,
    cipher_type INTEGER NOT NULL CHECK (cipher_type BETWEEN 1 AND 8),
    data TEXT NOT NULL,
    is_favorite BOOLEAN NOT NULL DEFAULT 0 CHECK (is_favorite IN (0, 1)),
    folder_id TEXT,
    deleted_at TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    archived_at TEXT,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (folder_id) REFERENCES folders(id) ON DELETE SET NULL
);

CREATE TABLE devices (
    user_id TEXT NOT NULL,
    device_id TEXT NOT NULL,
    name TEXT NOT NULL,
    device_type INTEGER NOT NULL,
    session_token TEXT NOT NULL,
    push_token TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    push_id TEXT,
    PRIMARY KEY (user_id, device_id),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE folders (
    id TEXT PRIMARY KEY NOT NULL,
    user_id TEXT NOT NULL,
    name TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE global_domains_cache (
    id INTEGER PRIMARY KEY NOT NULL CHECK (id = 1),
    next_refresh_at INTEGER NOT NULL
);

CREATE TABLE global_equivalent_domains (
    type INTEGER PRIMARY KEY NOT NULL,
    sort_order INTEGER NOT NULL,
    domains_json TEXT NOT NULL
);

CREATE TABLE jwt_keys (
    id TEXT PRIMARY KEY NOT NULL CHECK (id = 'global'),
    access_secret TEXT NOT NULL CHECK (length(access_secret) > 0),
    refresh_secret TEXT NOT NULL CHECK (length(refresh_secret) > 0)
);

CREATE TABLE sends (
    id TEXT PRIMARY KEY NOT NULL,
    user_id TEXT NOT NULL,
    name TEXT NOT NULL,
    notes TEXT,
    send_type INTEGER NOT NULL CHECK (send_type IN (0, 1)),
    data TEXT NOT NULL,
    encrypted_key TEXT NOT NULL,
    password_hash TEXT,
    password_salt TEXT,
    password_iterations INTEGER,
    max_access_count INTEGER CHECK (max_access_count IS NULL OR max_access_count >= 0),
    access_count INTEGER NOT NULL DEFAULT 0 CHECK (access_count >= 0),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    expires_at TEXT,
    deletes_at TEXT NOT NULL,
    is_disabled INTEGER NOT NULL DEFAULT 0,
    is_email_hidden INTEGER NOT NULL DEFAULT 0,
    access_stamp TEXT NOT NULL,
    file_id TEXT,
    file_size_bytes INTEGER NOT NULL DEFAULT 0 CHECK (file_size_bytes >= 0),
    upload_state INTEGER NOT NULL DEFAULT 0 CHECK (upload_state IN (0, 1, 2)),
    storage_key TEXT,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE storage_cleanup_jobs (
    object_key TEXT PRIMARY KEY NOT NULL,
    created_at TEXT NOT NULL,
    generation TEXT NOT NULL DEFAULT (lower(hex(randomblob(16))))
);

CREATE TABLE turnstile_redemptions (
